#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 5

int head = 0;
int count = 0;
long items[MAX_SIZE];

void enqueue(long item) {
    if (count == MAX_SIZE) {
        printf("FULL\n");
        return;
    }
    items[(head + count) % MAX_SIZE] = item;
    count++;
    printf("ENQ %ld\n", item);
}

void dequeue() {
    if (count == 0) {
        printf("EMPTY\n");
        return;
    }
    long item = items[head];
    head = (head + 1) % MAX_SIZE;
    count--;
    printf("DEQ %ld\n", item);
}

void print_front() {
    if (count == 0) {
        printf("EMPTY\n");
        return;
    }
    printf("FRONT %ld\n", items[head]);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (arg[0] == 'E') {
            long item = strtol(arg + 1, NULL, 10);
            enqueue(item);
        } else if (arg[0] == 'D') {
            dequeue();
        } else if (arg[0] == 'F') {
            print_front();
        } else {
            printf("ERR\n");
        }
    }
    return 0;
}
